require 'thread'

class Counter
  def initialize(initial_value = 0)
    @value = initial_value
    @mutex = Mutex.new
  end

  def increment(amount = 1)
    @mutex.synchronize { @value += amount }
  end

  def decrement(amount = 1)
    @mutex.synchronize { @value -= amount }
  end

  def value
    @mutex.synchronize { @value }
  end

  def reset(value = 0)
    @mutex.synchronize { @value = value }
  end
end
